patch:
diff --git a/tests/repro/no-unused-expressions-use-strict.js b/tests/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..c6db2a2
--- /dev/null
+++ b/tests/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,18 @@
+"use strict";
+// Repro for: no-unused-expressions reports 'use strict' in 9.25.0
+const { Linter } = require("../../lib/api");
+const linter = new Linter();
+const code = "'use strict';\nfunction f() { 'use strict'; return 1; }\n";
+let failed = false;
+for (const ecmaVersion of [3, 5, 2015, "latest"]) {
+	for (const sourceType of ["script", "commonjs"]) {
+		const msgs = linter.verify(code, {
+			languageOptions: { ecmaVersion, sourceType },
+			rules: { "no-unused-expressions": "error" },
+		});
+		const errs = msgs.map(m => `${m.line}:${m.column} ${m.ruleId || "fatal"}: ${m.message}`);
+		if (errs.length) failed = true;
+		console.log(`ecmaVersion=${ecmaVersion} sourceType=${sourceType}: ${errs.length ? errs.join(" | ") : "no errors"}`);
+	}
+}
+process.exitCode = failed ? 1 : 0;
